'use strict';
// Illustrations are representative categories, never retailer/product photographs.
const INGREDIENT_ART={pork:0,ribs:0,chicken:1,beef:2,salmon:3,fish:4,shrimp:5,tofu:6,egg:7,bokchoy:8,spinach:8,waterSpinach:8,broccoli:9,carrot:10,tomato:11,potato:12,pumpkin:13,mushroom:14,scallion:15};
function ingredientVector(id){let shapes='';const bottle=['fishSauce','soy','oil','coconut','broth','vegBroth'].includes(id),jar=['salt','sugar','pepper','starch','miso'].includes(id);
 if(bottle){const color=({fishSauce:'#a45a2d',soy:'#533b28',oil:'#e7bc53',coconut:'#dfe7cf',broth:'#d7b873',vegBroth:'#bdc392'})[id];shapes=`<rect x="36" y="9" width="28" height="14" rx="4" fill="#48624a"/><path d="M40 22h20v13q15 6 15 19v36q0 8-9 8H34q-9 0-9-8V54q0-13 15-19z" fill="${color}"/><rect x="30" y="52" width="40" height="29" rx="6" fill="#f3ead2"/><path d="M40 68q10-14 20 0q-10 13-20 0" fill="#75935f"/><path d="M34 42v40" stroke="#fff" stroke-width="4" opacity=".4"/>`}
 else if(jar){const color=id==='pepper'?'#7e6650':id==='miso'?'#ad895b':'#e6dfca';shapes=`<rect x="24" y="27" width="52" height="62" rx="13" fill="${color}"/><rect x="21" y="18" width="58" height="18" rx="7" fill="#6c8566"/><path d="M34 48h32v25H34z" fill="#faf3de"/><path d="M43 59h14" stroke="#91a47a" stroke-width="4"/>`}
 else if(['cucumber','gourd','okra','bean','peas'].includes(id)){const color=id==='gourd'?'#a8bd76':'#6d9c58';for(let i=0;i<3;i++)shapes+=`<rect x="${22+i*19}" y="${18+i*7}" width="17" height="66" rx="9" fill="${color}" transform="rotate(${i*12-12} 50 50)"/><path d="M${30+i*19} ${25+i*7}v43" stroke="#b7cf91" stroke-width="2"/>`;if(id==='peas')for(let i=0;i<4;i++)shapes+=`<circle cx="49" cy="${38+i*10}" r="5" fill="#c4d7a0"/>`}
 else if(id==='onion'){shapes='<path d="M47 27q-8-11 0-20l10 1q-7 11 1 20q30 12 28 38q-4 29-35 29q-37-2-37-29q0-28 33-39" fill="#cba07d"/><path d="M48 31q-26 38 0 57m6-57q25 33 1 57m-3-57v57" fill="none" stroke="#e9c9a8" stroke-width="4"/>'}
 else if(id==='garlic'){shapes='<path d="M48 12l12 1l-3 23q26 10 26 33q-2 25-32 25q-33 0-34-25q0-22 30-33z" fill="#ece4d0"/><path d="M47 42q-24 23-8 45m15-45q26 24 10 45m-13-44v44" fill="none" stroke="#cbbda9" stroke-width="3"/>'}
 else if(id==='ginger'){shapes='<path d="M22 71q-11-9 0-19l18-2l-3-18q-3-14 11-13q11 0 13 14l3 14l15-9q12-5 17 8q3 11-11 17l-20 7l-8 18q-5 13-16 8q-11-5-3-21z" fill="#d2ad73"/><path d="M39 56l14 10m1-22l9 10m-20 20l11 5" stroke="#aa8656" stroke-width="3"/>'}
 else if(id==='pineapple'){shapes='<path d="M50 36L25 8l19 13L50 3l8 20L77 10L61 39" fill="#648b50"/><ellipse cx="50" cy="66" rx="28" ry="33" fill="#d6b45c"/><path d="M29 49l37 36M25 64l28 28M43 36l32 36M71 49L34 85M75 64L47 92M57 36L25 72" stroke="#b19345" stroke-width="2"/>'}
 else if(id==='lime'){shapes='<circle cx="49" cy="57" r="31" fill="#9eb45c"/><path d="M48 26q2-20 23-17q-1 18-23 17" fill="#587f45"/><circle cx="41" cy="45" r="9" fill="#c3d18c" opacity=".5"/>'}
 else if(id==='corn'){shapes='<ellipse cx="50" cy="54" rx="23" ry="39" fill="#dfc36b"/><path d="M30 89Q6 69 13 40q13 10 24 43m26-1q8-34 23-45q8 30-18 53" fill="#8ba06b"/>';for(let x=37;x<65;x+=9)for(let y=25;y<86;y+=12)shapes+=`<rect x="${x}" y="${y}" width="6" height="9" rx="2" fill="#f5dc8d"/>`}
 else if(['herbs','lemongrass','cabbage','seaweed'].includes(id)){const color=id==='seaweed'?'#4f6754':'#7d9b60';for(let i=0;i<7;i++){const x=22+i*9;shapes+=`<path d="M50 94Q${x} 60 ${x} 20" fill="none" stroke="#9caf70" stroke-width="4"/><ellipse cx="${x}" cy="${30+(i%3)*12}" rx="${id==='lemongrass'?4:12}" ry="${id==='lemongrass'?26:20}" fill="${color}" transform="rotate(${(i-3)*10} ${x} 45)"/>`}}
 else if(id==='fishBall'||id==='wonton'){for(let i=0;i<6;i++){const x=25+i%3*25,y=36+Math.floor(i/3)*32;shapes+=id==='fishBall'?`<circle cx="${x}" cy="${y}" r="15" fill="#e7d8bf"/><path d="M${x-8} ${y-6}q8-8 15 0" stroke="#fcf5e4" fill="none" stroke-width="3"/>`:`<path d="M${x-16} ${y+11}l7-26l13 5l11 20l-13 9z" fill="#e8ce86"/><path d="M${x-8} ${y+4}l12-10" stroke="#bcaa71" stroke-width="2"/>`}}
 else if(['cookedRice','cookedChicken'].includes(id)){shapes='<ellipse cx="50" cy="45" rx="39" ry="25" fill="#dedac8"/><path d="M12 44q2 48 38 49q36-1 38-49z" fill="#e9e5d4"/><ellipse cx="50" cy="43" rx="34" ry="21" fill="#fbf2d9"/>';for(let i=0;i<20;i++){const x=23+i*17%56,y=30+i*11%25;shapes+=`<path d="M${x} ${y}l5 2" stroke="${id==='cookedChicken'?'#b9976b':'#d8cfb4'}" stroke-width="3" stroke-linecap="round"/>`}}
 else {const noodles=['noodle','riceNoodle','eggNoodle','vermicelli','udon','pasta','huTieu','banhCanh'].includes(id);shapes='<path d="M24 14h52l4 77H20z" fill="#e9dfbb"/><rect x="22" y="22" width="56" height="12" fill="#75926b"/><rect x="29" y="42" width="42" height="38" rx="5" fill="#fbf4dc"/>';for(let i=0;i<6;i++)shapes+=noodles?`<path d="M${35+i*5} 47q-10 14 0 27" stroke="#cbb476" fill="none" stroke-width="3"/>`:`<path d="M${35+i*4} ${49+i%2*14}l3 7" stroke="#d3c6a2" stroke-width="3" stroke-linecap="round"/>`}
 return `<svg viewBox="0 0 100 110" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><ellipse cx="50" cy="101" rx="34" ry="5" fill="#627347" opacity=".1"/>${shapes}</svg>`;
}
function ingredientArtwork(id){if(Object.hasOwn(INGREDIENT_ART,id)){const n=INGREDIENT_ART[id];return `<span class="ingredient-art ingredient-sheet" aria-hidden="true" style="--art-x:${n%4*100/3}%;--art-y:${Math.floor(n/4)*100/3}%"></span>`}return `<span class="ingredient-art ingredient-vector" aria-hidden="true">${ingredientVector(id)}</span>`}
function dishArtworkCell(r){if(!r)return null;const name=normalizeText(r.name);if(r.category==='noodle'){if(name.includes('chao')||r.ingredients.some(i=>i.id==='cookedRice'))return 13;if(r.ingredients.some(i=>i.id==='wonton'))return 12;if(r.protein==='beef')return 11;return 10}if(r.category==='soup'){if(r.ingredients.some(i=>i.id==='egg'))return 14;if(r.ingredients.some(i=>i.id==='pumpkin'))return 7;return 6}if(r.category==='veg')return r.ingredients.some(i=>i.id==='mushroom'||i.id==='bean')?9:8;if(r.category==='main'){if(r.protein==='pork'&&r.ingredients.some(i=>i.id==='egg'))return 0;if(r.protein==='chicken')return 1;if(r.protein==='beef')return 2;if(r.protein==='fish')return name.includes('hap')?15:3;if(r.protein==='shrimp')return 4;if(r.protein==='plant')return 5}return null}
const vectorFoodArt=foodArt;
foodArt=function(r,hero=false){const cell=dishArtworkCell(r);if(cell===null)return vectorFoodArt(r,hero);const label=typeof appLanguage!=='undefined'&&appLanguage==='en'?'Representative dish illustration':'Minh họa nhóm món, không phải ảnh công thức';return `<span class="food-illustration dish-sheet" role="img" aria-label="${label}" style="--art-x:${cell%4*100/3}%;--art-y:${Math.floor(cell/4)*100/3}%"></span>`};
function decorateIngredientArt(){
 $$('.shop-purchase-row').forEach(row=>{const target=$('[data-action="ingredient-detail"]',row);if(target&&!$('.ingredient-art',target))target.insertAdjacentHTML('afterbegin',ingredientArtwork(target.dataset.id))});
 $$('.weekly-dish').forEach(button=>{const r=currentWeek().days[button.dataset.date]?.[button.dataset.type]?.recipes[+button.dataset.index];if(r&&!$('.weekly-dish-art',button)){const span=document.createElement('span');span.className='weekly-dish-art';span.innerHTML=foodArt(r);button.prepend(span)}});
 $$('.inventory-card').forEach(card=>{const name=$('h3',card)?.textContent,id=Object.keys(INGREDIENTS).find(id=>INGREDIENTS[id][0]===name||typeof INGREDIENT_EN!=='undefined'&&INGREDIENT_EN[id]===name);if(id&&$('.inventory-icon',card))$('.inventory-icon',card).innerHTML=ingredientArtwork(id)});
}
